/** A person, or another pool, in a pool, with their share percent of it. */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    /** The member person; null when the member is a pool. */
    @Column(name = "person_id")
    private Long personId;

    /** The member pool; null when the member is a person. */
    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false)
    private BigDecimal share;

    /** The first day of the membership, included; null: no start. */
    @Column(name = "from_date")
    private LocalDate from;

    /** The last day of the membership, included; null: no end. */
    @Column(name = "to_date")
    private LocalDate to;

    protected PoolMember() {
    }

    public PoolMember(String sheetId, Long poolId, Long personId, BigDecimal share) {
        this.sheetId = sheetId;
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool as a member of another. */
    public static PoolMember ofPool(String sheetId, Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember m = new PoolMember(sheetId, poolId, null, share);
        m.memberPoolId = memberPoolId;
        return m;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    public void setShare(BigDecimal share) {
        this.share = share;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    /** Dates the membership (null: no bound). */
    public void setDates(LocalDate from, LocalDate to) {
        this.from = from;
        this.to = to;
    }

    /** Whether the membership's dates include the day. */
    public boolean includes(LocalDate day) {
        return (from == null || !day.isBefore(from)) && (to == null || !day.isAfter(to));
    }

    /** Moves the membership to another person, keeping its place in the order members were added. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }
}
