422	        sheets.lock(sheetId);
423	        Pool pool = pool(sheetId, poolId);
424	        Person person = people.findByIdAndSheetId(personId, sheetId)
425	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Choose a person."));
426	        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
427	            throw new ResponseStatusException(HttpStatus.CONFLICT,
428	                    person.getName() + " is already in " + pool.getName() + ".");
429	        }
430	        PoolMember member = new PoolMember(sheetId, pool.getId(), person.getId(), scaled);
431	        member.setDates(from, to);
432	        PoolMember added = members.saveAndFlush(member);
433	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " pool=" + pool.getName()
434	                + " name=" + person.getName() + " share=" + scaled.toPlainString() + dated(from, to));
435	        return added;
436	    }
437	
438	    /**
439	     * Adds another pool to the pool with a share; refused when the share is not valid (as for a person), when the
440	     * member pool is already a member of a pool (this or another), when it is the pool itself or contains it through
441	     * any chain, or when the chain of pools would be more than {@value #MAX_DEPTH} deep.
442	     */
443	    @Transactional
444	    public PoolMember addPoolMember(String by, String sheetId, Long poolId, Long memberPoolId,
445	            BigDecimal share, LocalDate from, LocalDate to) {
446	        BigDecimal scaled = validShare(share);
447	        validDates(from, to);
448	        sheets.lock(sheetId);
449	        Pool pool = pool(sheetId, poolId);
450	        Pool member = pools.findById(memberPoolId).filter(p -> p.getSheetId().equals(sheetId))
451	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Choose a member."));
452	        // each pool that is a member of another, to the pool it is in
453	        Map<Long, Long> parent = new HashMap<>();
454	        for (PoolMember m : members.findBySheetIdOrderByIdAsc(sheetId)) {
455	            if (m.getMemberPoolId() != null) {
456	                parent.put(m.getMemberPoolId(), m.getPoolId());
457	            }
458	        }
459	        int above = 0;
460	        for (Long p = pool.getId(); p != null; p = parent.get(p)) {
461	            if (p.equals(member.getId())) {
462	                throw new ResponseStatusException(HttpStatus.CONFLICT,
463	                        member.getName() + " would contain itself through " + pool.getName() + ".");
464	            }
465	            above++;
466	        }
467	        if (parent.containsKey(member.getId())) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT, member.getName() + " is already a member of a pool.");
469	        }
470	        if (above + height(member.getId(), parent) > MAX_DEPTH) {
471	            throw new ResponseStatusException(HttpStatus.CONFLICT,
472	                    "A chain of pools may be at most " + MAX_DEPTH + " deep.");
473	        }
474	        PoolMember membership = PoolMember.ofPool(sheetId, pool.getId(), member.getId(), scaled);
475	        membership.setDates(from, to);
476	        PoolMember added = members.saveAndFlush(membership);
477	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " pool=" + pool.getName()
478	                + " name=" + member.getName() + " share=" + scaled.toPlainString() + dated(from, to));
479	        return added;
480	    }
481	
482	    /** How many pools deep the chain below a pool goes, the pool itself counted. */
483	    private static int height(Long poolId, Map<Long, Long> parent) {
484	        int most = 0;
485	        for (Map.Entry<Long, Long> e : parent.entrySet()) {
486	            if (e.getValue().equals(poolId)) {
487	                most = Math.max(most, height(e.getKey(), parent));
488	            }
489	        }
490	        return most + 1;
491	    }
492	
493	    private Pool pool(String sheetId, Long poolId) {
494	        return pools.findById(poolId).filter(p -> p.getSheetId().equals(sheetId))
495	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
496	    }
497	
498	    /** Refused when both dates are given and the to-date is before the from-date. */
499	    private static void validDates(LocalDate from, LocalDate to) {
500	        if (from != null && to != null && to.isBefore(from)) {
501	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
502	                    "A membership cannot end before it starts.");
503	        }
504	    }
505	
506	    /** The audit fields for the dates given: from=<date> and to=<date>, each only when given. */
507	    private static String dated(LocalDate from, LocalDate to) {
508	        return (from == null ? "" : " from=" + from) + (to == null ? "" : " to=" + to);
509	    }
510	
511	    /** The share at two decimals; refused unless more than 0.00 and at most 100.00 with up to two decimals. */
512	    private static BigDecimal validShare(BigDecimal share) {
513	        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
514	                || share.stripTrailingZeros().scale() > 2) {
515	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
516	                    "Enter a share of more than 0.00 and at most 100.00, with up to two decimals.");
517	        }
518	        return share.setScale(2, RoundingMode.UNNECESSARY);
519	    }
520	}
