749	package net.officefloor.hq.app.crew;
750	
751	import java.util.List;
752	import net.officefloor.hq.app.Audit;
753	import net.officefloor.hq.app.person.Person;
754	import net.officefloor.hq.app.person.PersonRepository;
755	import net.officefloor.hq.app.sheet.SheetService;
756	import org.springframework.http.HttpStatus;
757	import org.springframework.stereotype.Service;
758	import org.springframework.transaction.annotation.Transactional;
759	import org.springframework.web.server.ResponseStatusException;
760	
761	/**
762	 * The sheet's crews and their members. A crew has a name (trimmed, not blank, at most once on the sheet) and a lead
763	 * chosen from the sheet's people; its members are other people of the sheet, each at most once, never its lead. A
764	 * person may lead or be in several crews.
765	 */
766	@Service
767	public class CrewService {
768	
769	    private final CrewRepository crews;
770	    private final CrewMemberRepository members;
771	    private final PersonRepository people;
772	    private final SheetService sheets;
773	    private final Audit audit;
774	
775	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
776	            SheetService sheets, Audit audit) {
777	        this.crews = crews;
778	        this.members = members;
779	        this.people = people;
780	        this.sheets = sheets;
781	        this.audit = audit;
782	    }
783	
784	    /** The sheet's crews, in the order they were added. */
785	    @Transactional(readOnly = true)
786	    public List<Crew> list(String sheetId) {
787	        return crews.findBySheetIdOrderByIdAsc(sheetId);
788	    }
789	
790	    /** The members of every crew on the sheet, in the order they were added. */
791	    @Transactional(readOnly = true)
792	    public List<CrewMember> members(String sheetId) {
793	        return members.findBySheetIdOrderByIdAsc(sheetId);
794	    }
795	
796	    /** Adds a crew under its name, trimmed, led by the person; refused when blank, already a crew's name, or no lead. */
797	    @Transactional
798	    public Crew add(String by, String sheetId, String name, Long leadId) {
799	        String key = name == null ? "" : name.strip();
800	        if (key.isEmpty()) {
801	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Enter a crew name.");
802	        }
803	        sheets.lock(sheetId);
804	        Person lead = person(sheetId, leadId, "Choose a lead.");
805	        if (crews.existsBySheetIdAndName(sheetId, key)) {
806	            throw new ResponseStatusException(HttpStatus.CONFLICT, key + " is already a crew.");
807	        }
808	        Crew added = crews.saveAndFlush(new Crew(sheetId, key, lead.getId()));
809	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + by + " name=" + key + " lead=" + lead.getName());
810	        return added;
811	    }
812	
813	    /** Adds the person to the crew; refused when they lead it or are already in it. */
814	    @Transactional
815	    public CrewMember addMember(String by, String sheetId, Long crewId, Long personId) {
816	        sheets.lock(sheetId);
817	        Crew crew = crews.findById(crewId).filter(c -> c.getSheetId().equals(sheetId))
818	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew."));
819	        Person person = person(sheetId, personId, "Choose a person.");
820	        if (person.getId().equals(crew.getLeadId())) {
821	            throw new ResponseStatusException(HttpStatus.CONFLICT,
822	                    person.getName() + " leads " + crew.getName() + ".");
823	        }
824	        if (members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
825	            throw new ResponseStatusException(HttpStatus.CONFLICT,
826	                    person.getName() + " is already in " + crew.getName() + ".");
827	        }
828	        CrewMember added = members.saveAndFlush(new CrewMember(sheetId, crew.getId(), person.getId()));
829	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " crew=" + crew.getName()
830	                + " name=" + person.getName());
831	        return added;
832	    }
833	
834	    /**
835	     * A person merged into another: the crews they lead pass to the other, and their memberships too; a membership the
836	     * other already has, or of a crew the other now leads, is dropped.
837	     */
838	    @Transactional
839	    public void merged(String sheetId, Long from, Long into) {
840	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
841	        for (Crew c : all) {
842	            if (from.equals(c.getLeadId())) {
843	                c.setLeadId(into);
844	                crews.save(c);
845	            }
846	        }
847	        crews.flush();
848	        List<CrewMember> memberships = members.findBySheetIdOrderByIdAsc(sheetId);
849	        for (CrewMember m : memberships) {
850	            boolean intoLeads = all.stream().anyMatch(c -> c.getId().equals(m.getCrewId()) && into.equals(c.getLeadId()));
851	            if (into.equals(m.getPersonId()) && intoLeads) {
852	                members.delete(m);
853	            } else if (from.equals(m.getPersonId())) {
854	                boolean intoIn = memberships.stream()
855	                        .anyMatch(o -> o.getCrewId().equals(m.getCrewId()) && into.equals(o.getPersonId()));
856	                if (intoIn || intoLeads) {
857	                    members.delete(m);
858	                } else {
859	                    m.setPersonId(into);
860	                    members.save(m);
861	                }
862	            }
863	        }
864	        members.flush();
865	    }
866	
867	    /** A person leaving the sheet: their memberships are dropped, and so are the crews they lead, with their members. */
868	    @Transactional
869	    public void left(String sheetId, Long personId) {
870	        List<Crew> led = crews.findBySheetIdOrderByIdAsc(sheetId).stream()
871	                .filter(c -> personId.equals(c.getLeadId())).toList();
872	        members.deleteAll(members.findBySheetIdOrderByIdAsc(sheetId).stream()
873	                .filter(m -> personId.equals(m.getPersonId())
874	                        || led.stream().anyMatch(c -> c.getId().equals(m.getCrewId())))
875	                .toList());
876	        members.flush();
877	        crews.deleteAll(led);
878	        crews.flush();
879	    }
880	
881	    private Person person(String sheetId, Long personId, String refusal) {
882	        if (personId == null) {
883	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, refusal);
884	        }
885	        return people.findByIdAndSheetId(personId, sheetId)
886	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, refusal));
887	    }
888	}
